function sortDate(a,b){return String(b.date||'').localeCompare(String(a.date||''));}
function machineOptions(){return '<option value="">Choose machine</option>'+state.machines.filter(function(m){return m.status!=='Inactive';}).map(function(m){return '<option value="'+esc(m.id)+'">'+esc(m.name)+' · '+esc(m.plate||m.type)+'</option>';}).join('');}
function tripRows(rows){if(!rows.length)return '<p class="mach-note">No trip records yet.</p>';return rows.map(function(t){var m=machine(t.machineId),c=customer(t.customerId),d=driver(m&&m.driverId);return '<div class="mach-record"><div class="mach-record-top"><b>'+esc(t.ticket||'Trip')+' · '+money(t.amount)+'</b><small>'+esc(t.date)+'</small></div><span>'+esc(m?m.name:'Machine')+' · '+esc(c?c.name:'Customer')+'</span><span>'+esc(t.material)+' · '+(Number(t.tripCount)||1)+' trip(s)'+(t.quantity?' · '+esc(t.quantity)+' '+esc(t.unit):'')+'</span><span>'+esc(t.origin||'')+' → '+esc(t.destination||'')+'</span><span>Driver: '+esc(d?d.name:'Not assigned')+'</span><span>Rate: '+money(t.rate)+' '+esc(t.basis==='trip'?'per trip':t.basis==='tonne'?'per tonne':'per m³')+'</span><span>'+tripStatus(t)+' · Paid '+money(tripPaid(t.id))+' · Due '+money(tripDue(t))+'</span>'+editButton('trip',t.id)+'</div>';}).join('');}

function editButton(kind,id){return '<button type="button" class="secondary" data-edit-kind="'+kind+'" data-edit-id="'+esc(id)+'">Edit</button>';}
function field(label,name,value,type){return '<label>'+label+'<input name="'+name+'" type="'+(type||'text')+'" value="'+esc(value==null?'':value)+'"></label>';}
function pick(label,name,items,value){return '<label>'+label+'<select name="'+name+'">'+items.map(function(x){return '<option value="'+esc(x.value)+'" '+(String(x.value)===String(value)?'selected':'')+'>'+esc(x.label)+'</option>';}).join('')+'</select></label>';}
