// Ensure all registered machines own a permanent CashBook. Existing machine expenses are
// linked once; source IDs make the migration safe to repeat without duplicate entries.
var migrated=false;
state.machines.forEach(function(m){if(!m.driverId){var old=state.trips.find(function(t){return t.machineId===m.id&&t.driverId;});if(old){m.driverId=old.driverId;migrated=true;}}var id=machineBook(m);if(id&&m.cashBookId!==id){m.cashBookId=id;migrated=true;}});
state.trips.forEach(function(t){if(t.driverId){delete t.driverId;migrated=true;}});
state.drivers.forEach(function(d){var owner=state.machines.find(function(m){return m.driverId===d.id;});if(owner&&d.machineId!==owner.id){d.machineId=owner.id;migrated=true;}});
state.expenses.forEach(function(x){var m=machine(x.machineId);if(m){var id=machineBook(m);if(id&&!x.bookId){x.bookId=id;postCash(m,'expense',x.id,{type:'out',amount:x.amount,date:x.date,category:x.type,party:'',note:x.note||''});migrated=true;}}});
